func OrderAPIGetTotal(ctx context.Context, db DBTX, id float64) (*float64, error) {
	var value *float64
	err := db.QueryRowContext(ctx, "SELECT SHOP.ORDER_API.GET_TOTAL(:1) FROM DUAL", id).Scan(&value)
	return value, err
}

// BillingListOpenInvoicesResult holds what SHOP.BILLING.LIST_OPEN_INVOICES returns.
type BillingListOpenInvoicesResult struct {
	Result []map[string]any
}

// BillingListOpenInvoices calls SHOP.BILLING.LIST_OPEN_INVOICES.
func BillingListOpenInvoices(ctx context.Context, db DBTX, customerID float64) (BillingListOpenInvoicesResult, error) {
	var out BillingListOpenInvoicesResult
	var resultCursor driver.Rows
	if _, err := db.ExecContext(ctx, "BEGIN SHOP.BILLING.LIST_OPEN_INVOICES(P_CUSTOMER_ID => :P_CUSTOMER_ID, P_RESULT => :P_RESULT); END;", sql.Named("P_CUSTOMER_ID", customerID), sql.Named("P_RESULT", sql.Out{Dest: &resultCursor})); err != nil {
		return out, err
	}
	resultRows, err := godror.WrapRows(ctx, db, resultCursor)
	if err != nil {
		return out, err
	}
	if out.Result, err = scanMaps(resultRows); err != nil {
		return out, err
	}
	return out, nil
}

// BillingInvoiceTotal calls SHOP.BILLING.INVOICE_TOTAL.
func BillingInvoiceTotal(ctx context.Context, db DBTX, invoiceID float64) (*float64, error) {
	var value *float64
	err := db.QueryRowContext(ctx, "SELECT SHOP.BILLING.INVOICE_TOTAL(:1) FROM DUAL", invoiceID).Scan(&value)
	return value, err
}

// DBTX is satisfied by *sql.DB, *sql.Conn and *sql.Tx.
type DBTX interface {
	ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error)
	QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows, error)
	QueryRowContext(ctx context.Context, query string, args ...any) *sql.Row
}

// execAffectedOne turns "0 rows affected" into sql.ErrNoRows.
func execAffectedOne(res sql.Result, err error) error {
	if err != nil {
		return err
	}
	n, err := res.RowsAffected()
	if err != nil {
		return err
	}
	if n == 0 {
		return sql.ErrNoRows
	}
	return nil
}

// scanMaps reads every row of an untyped result set into maps keyed by column name, then closes rows.
func scanMaps(rows *sql.Rows) ([]map[string]any, error) {
	defer rows.Close()
	cols, err := rows.Columns()
	if err != nil {
		return nil, err
	}
	var out []map[string]any
	for rows.Next() {
		values := make([]any, len(cols))
		ptrs := make([]any, len(cols))
		for i := range values {
			ptrs[i] = &values[i]
		}
		if err := rows.Scan(ptrs...); err != nil {
			return nil, err
		}
		row := make(map[string]any, len(cols))
		for i, c := range cols {
			row[c] = values[i]
		}
		out = append(out, row)
	}
	return out, rows.Err()
}
